import { Resend } from "resend";

let client: Resend | undefined;

function getClient(): Resend | undefined {
  if (!process.env.RESEND_API_KEY) return undefined;
  client ??= new Resend(process.env.RESEND_API_KEY);
  return client;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

type Message = { to: string; subject: string; html: string; text: string };

// Email failures are logged, never thrown: a failed email must not break the request that caused it.
async function send({ to, subject, html, text }: Message): Promise<boolean> {
  const resend = getClient();
  const from = process.env.RESEND_FROM_EMAIL;
  if (!resend || !from) {
    console.warn(`[email] RESEND_API_KEY / RESEND_FROM_EMAIL not set, skipping "${subject}"`);
    return false;
  }
  try {
    const { error } = await resend.emails.send({ from, to, subject, html, text });
    if (error) {
      console.error(`[email] Resend refused "${subject}": ${error.name}: ${error.message}`);
      return false;
    }
    return true;
  } catch (err) {
    console.error(`[email] failed to send "${subject}"`, err);
    return false;
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    html: `<p>Hi ${name},</p><p>Welcome to Notely. Your account is ready.</p>`,
    text: `Hi ${user.name},\n\nWelcome to Notely. Your account is ready.`,
  });
}

export function sendPasswordResetEmail(user: { email: string; name: string }, resetUrl: string) {
  const name = escapeHtml(user.name);
  const url = escapeHtml(resetUrl);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    html: `<p>Hi ${name},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour.</p><p>If you didn't request this, you can ignore this email.</p>`,
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\nThis link expires in 1 hour.\n\nIf you didn't request this, you can ignore this email.`,
  });
}
EOF
